controls.uiScript:
if(!`panel -q -exists clipEditorPanel1`) {
	int $menusOkayInPanels = `optionVar -q allowMenusInPanels`;
	string $panelName = "clipEditorPanel1";
	scriptedPanel -unParent  -type "clipEditorPanel" -l (localizedPanelLabel("Trax Editor")) -mbv $menusOkayInPanels  clipEditorPanel1;

			$editorName = clipEditorNameFromPanel($panelName);
            clipEditor -e 
                -displayValues 0
                -snapTime "none" 
                -snapValue "none" 
                -initialized 0
                -manageSequencer 0 
                $editorName;
} else {
	scriptedPanel -e -unParent clipEditorPanel1;
}
scriptedPanel -e -parent clipEditorPanel1Window clipEditorPanel1;

